// legibleInkFor returns srcHex when it clears minRatio against EVERY ground,
// otherwise the first palette colour that does, otherwise black or white.
//
// Requiring ALL grounds is the deliberate choice: a component may place the
// same ink on the page and on a card (dartsonline does exactly that — the
// eyebrow at 1.04 on background, the card link at 1.11 on the derived
// card_bg), and one variable cannot be right for two grounds unless it is
// right for the worse of them. On a dark palette background and surface sit
// close in lightness, so a value clearing both is normally easy to find.
func legibleInkFor(srcHex string, grounds []string, palette map[string]string, minRatio float64) (hex, source string) {
	clearsAll := func(candidate string) bool {
		for _, g := range grounds {
			if g == "" {
				continue
			}
			ratio, err := wcagContrastRatio(candidate, g)
			if err != nil || ratio < minRatio {
				return false
			}
		}
		return true
	}
	if srcHex != "" && clearsAll(srcHex) {
		return srcHex, "source:unchanged"
	}
	for _, key := range []string{"text", "accent", "text_muted", "secondary"} {
		if v, ok := palette[key]; ok && v != "" && clearsAll(v) {
			return v, "palette:" + key
		}
	}
	// Nothing in the palette survives every ground; fall back to whichever
	// achromatic extreme is worst-case best across them.
	if worstRatio("#ffffff", grounds) >= worstRatio("#000000", grounds) {
		return "#ffffff", "fallback:white"
	}
	return "#000000", "fallback:black"
}

// buildLegibleInkDefaults returns a renderer-owned :root block defining the
// ink companions a component can opt into. Returns "" when both are already
// defined in css.
//
// SCHEME-INDEPENDENT, unlike fillDarkSchemeSpecialisedSlots. That function is
// dark-only because a LIGHT LITERAL is only wrong on a dark site. "This ink is
// illegible on this ground" is true or false regardless of scheme, and two of
// the three measured hard-coded-ink sites are light (gaswholesalers #F4F1EB,
// finetuning #F5F3EF), so a dark-only guard cannot reach them.
//
// --color-accent-text is NOT a new name: darkSchemeDerivations has derived the
// `accent_text` slot since 2026-07-27 for precisely this purpose, and 0 of 18
// layouts declare it, so it has never reached one stylesheet. Emitting it here
// is what turns that dead derivation live.
func buildLegibleInkDefaults(css string, palette map[string]string, logger *zap.Logger) string {
	bg := lookupOrFallback(palette, "background", "")
	surface := lookupOrFallback(palette, "surface", "")
	if bg == "" {
		return "" // nothing to measure against; stay silent rather than guess
	}
	type inkVar struct {
		name, src string
		grounds   []string
	}
	wanted := []inkVar{
		// primary used as TEXT on the page and on a card.
		{"--color-primary-ink", palette["primary"], []string{bg, surface}},
		// text placed ON an accent fill — one ground, the fill itself.
		{"--color-accent-text", palette["text"], []string{palette["accent"]}},
	}
	var b strings.Builder
	var emitted, unchanged []string
	for _, w := range wanted {
		if w.src == "" || strings.Contains(css, w.name+":") {
			continue // undeterminable, or the stylesheet already has an opinion
		}
		hex, src := legibleInkFor(w.src, w.grounds, palette, inkMinContrast)
		b.WriteString("  " + w.name + ": " + hex + ";\n")
		if src == "source:unchanged" {
			unchanged = append(unchanged, w.name)
		} else {
			emitted = append(emitted, w.name+"<-"+src)
		}
	}
	if b.Len() == 0 {
		return ""
	}
	// A no-op emission and a substituted one are indistinguishable in the
	// output CSS, which is the property that let the original defect hide.
	logger.Info("buildLegibleInkDefaults: emitted ink companions a component can opt into",
		zap.Strings("substituted", emitted),
		zap.Strings("already_legible_left_as_is", unchanged))
	return "\n\n/* renderer-owned legible-ink companions (opt in via var(--x, <source>)) */\n:root {\n" +
		b.String() + "}\n"
}

// after the existing sectionDefaults append and buildTokenAliases append:

	// 10c. Ink companions. The palette already knows which of its colours can
	// be read on which ground; until now it had no way to TELL a component.
	// Additive and inert — a component reaches these only by opting in with
	// var(--color-primary-ink, var(--color-primary)), so an un-migrated
	// template renders byte-identically (bugs_open/122).
	if inkDefaults := buildLegibleInkDefaults(renderedCSS, mergedPalette, logger); inkDefaults != "" {
		renderedCSS = renderedCSS + inkDefaults
	}

// 1. dartsonline's real palette (primary #111520 on background #0E1019,
//    surface #1A1F2E): --color-primary-ink MUST differ from #111520 and MUST
//    clear 4.5 against BOTH grounds. Asserts the substitution happened AND is
//    correct, not merely that a value was written.
// 2. NO-OP CASE, the important one: a palette whose primary already clears
//    4.5 on both grounds emits primary's OWN value, and the log records it as
//    already_legible_left_as_is. A gate that fires on everything is as
//    useless as one that fires on nothing.
// 3. LIGHT scheme (background #F4F1EB, accent #E8A020 — gaswholesalers'
//    real values): the block is emitted. This is the assertion that pins the
//    deliberate divergence from fillDarkSchemeSpecialisedSlots' dark-only
//    boundary; if someone later 'tidies' this behind an isDarkHex guard the
//    test fails and says why.
// 4. Pre-defined name: css already containing '--color-primary-ink:' yields no
//    second definition for it, mirroring buildTokenAliases' contract.
//
// Each assertion will be proven load-bearing by deleting the corresponding
// branch and confirming a distinct failure message, per this repo's practice —
// a test that passes when the rule is gone is not a test.
